style.css:
@-moz-document domain("youtube.com") {
/* Yandere Simulator Dark Pink Theme Override */
    
    :root {
        --yt-spec-brand-background-solid: #1c050b !important;
        --yt-spec-general-background-a: #120206 !important;
        --yt-spec-general-background-b: #1c050b !important;
        --yt-spec-general-background-c: #260a12 !important;
        --yt-spec-base-background: #120206 !important;
        --yt-spec-raised-background: #1c050b !important;
        
        /* Text & Icon Colors (Yandere Pink & Soft White) */
        --yt-spec-text-primary: #ffb3c6 !important;
        --yt-spec-text-secondary: #ff85a2 !important;
        --yt-spec-icon-active-other: #ff4d6d !important;
        --yt-spec-icon-inactive: #a3707c !important;
        
        /* Video Player Progress Bar (Yandere Blood Red) */
        --yt-spec-static-brand-red: #c9184a !important;
        --ytd-video-primary-info-renderer-title-color: #ffb3c6 !important;
    }

    /* Change Sidebar and Top Nav Panels */
    ytd-app, 
    ytd-masthead, 
    #background.ytd-masthead,
    ytd-mini-guide-renderer,
    #guide-content.ytd-guide-renderer {
        background-color: #120206 !important;
    }

    /* Yandere Theme Buttons and Links */
    a.yt-simple-endpoint.yt-formatted-string,
    #video-title.ytd-rich-grid-media,
    #channel-name.ytd-video-meta-block {
        color: #ffb3c6 !important;
    }

    /* Video Player Progress Bar Colors */
    .ytp-play-progress, .ytp-scrubber-button {
        background: #ff4d6d !important;
    }
    
    .ytp-swatch-background-color {
        background-color: #ff4d6d !important;
    }

    /* Comment Section Boxes */
    ytd-comment-thread-renderer {
        background: #1c050b !important;
        border-radius: 8px;
        padding: 10px;
        margin-bottom: 8px;
        border: 1px solid #4a0e1b;
    }
}
